  parameters: {"type":"object","properties":{"content":{"type":"string","minLength":1,"maxLength":2000,"description":"星星内容（想许的愿/想记的话）"},"visibility":{"type":"string","enum":["visible","hidden"],"description":"visible=我们的瓶子；hidden=自己的私人瓶"},"mood_type":{"type":"string","maxLength":100,"description":"可选：星星的心情境况"},"mood_text":{"type":"string","maxLength":100,"description":"可选：写星时的一句话心情"},"note":{"type":"string","maxLength":500,"description":"可选：附注"},"idempotency_key":{"type":"string","minLength":1,"maxLength":128,"description":"幂等键：同键重试只写一颗"}},"required":["content","visibility","idempotency_key"],"additionalProperties":false}
